<?php require_once '../config/auth.php';$page_title='Follow-ups';$base='../';$rows=$pdo->query("SELECT f.*,c.name customer FROM followups f JOIN customers c ON c.id=f.customer_id ORDER BY f.due_at ASC")->fetchAll();include '../partials/header.php';?><div class="d-flex justify-content-between mb-3"><div><h4>Follow-ups</h4><p class="text-muted">Never miss a customer touchpoint.</p></div><a class="btn btn-primary" href="form.php">+ Schedule</a></div><div class="cardx table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Customer</th><th>Type</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['subject'])?></b><div class="small text-muted"><?=e($r['notes'])?></div></td><td><?=e($r['customer'])?></td><td><?=e(ucfirst($r['type']))?></td><td><?=date('M d, Y H:i',strtotime($r['due_at']))?></td><td><span class="status"><?=e(ucfirst($r['status']))?></span></td><td><?php if($r['status']=='pending'):?><a class="btn btn-sm btn-success" href="complete.php?id=<?=$r['id']?>">Complete</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php include '../partials/footer.php';?>